 import unittest
from candidate import poly, find_zero

class TestPolynomial(unittest.TestCase):
    def test_poly_normalcase(self):
        self.assertEqual(poly([1, 2], 3), 11)

    def test_poly_empty_coefficients(self):
        self.assertEqual(poly([]), 0)

    def test_poly_empty_point(self):
        self.assertEqual(poly([1, 2], None), None)

    def test_poly_none_coefficients(self):
        self.assertEqual(poly(None, 3), None)

    def test_poly_none_point(self):
        self.assertEqual(poly([1, 2], None), None)

    def test_poly_invalid_point(self):
        with self.assertRaises(TypeError):
            poly([1, 2], "x")

    def test_find_zero_normalcase(self):
        self.assertAlmostEqual(find_zero([1, 2]), -0.5)

    def test_find_zero_boundary_conditions(self):
        self.assertAlmostEqual(find_zero([1]), 0)
        self.assertAlmostEqual(find_zero([1, 2, 1]), 0.5)

    def test_find_zero_empty_coefficients(self):
        self.assertIsNone(find_zero([]))

    def test_find_zero_none_coefficients(self):
        self.assertIsNone(find_zero(None))

    def test_find_zero_invalid_coefficients(self):
        with self.assertRaises(TypeError):
            find_zero(["a", 2])

if __name__ == '__main__':
    unittest.main()
